-- CarbonX private application schema. Existing public project tables are not modified.
CREATE TABLE IF NOT EXISTS companies(id TEXT PRIMARY KEY,name TEXT NOT NULL,is_example INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL);CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,company_id TEXT NOT NULL REFERENCES companies(id),email TEXT UNIQUE NOT NULL,name TEXT NOT NULL,password_hash TEXT NOT NULL,role TEXT NOT NULL CHECK(role IN ('owner','reviewer','analyst')),created_at TEXT NOT NULL);CREATE TABLE IF NOT EXISTS sessions(id TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),csrf TEXT NOT NULL,expires TEXT NOT NULL);CREATE TABLE IF NOT EXISTS facilities(id TEXT PRIMARY KEY,company_id TEXT NOT NULL REFERENCES companies(id),name TEXT NOT NULL,latitude DOUBLE PRECISION NOT NULL,longitude DOUBLE PRECISION NOT NULL,boundary TEXT NOT NULL,created_at TEXT NOT NULL);CREATE TABLE IF NOT EXISTS reports(id TEXT PRIMARY KEY,company_id TEXT NOT NULL REFERENCES companies(id),facility_id TEXT REFERENCES facilities(id),name TEXT NOT NULL,year INTEGER NOT NULL,boundary TEXT NOT NULL,original_name TEXT NOT NULL,stored_name TEXT NOT NULL,sha256 TEXT NOT NULL,mime TEXT NOT NULL,size INTEGER NOT NULL,status TEXT NOT NULL,mode TEXT NOT NULL,page_count INTEGER NOT NULL DEFAULT 0,chunk_count INTEGER NOT NULL DEFAULT 0,warning TEXT NOT NULL DEFAULT '',archived INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL);CREATE TABLE IF NOT EXISTS pages(id TEXT PRIMARY KEY,company_id TEXT NOT NULL,report_id TEXT NOT NULL REFERENCES reports(id) ON DELETE CASCADE,number INTEGER NOT NULL,text TEXT NOT NULL,tables_json TEXT NOT NULL DEFAULT '[]',ocr INTEGER NOT NULL DEFAULT 0,UNIQUE(report_id,number));CREATE TABLE IF NOT EXISTS chunks(id TEXT PRIMARY KEY,company_id TEXT NOT NULL,report_id TEXT NOT NULL REFERENCES reports(id) ON DELETE CASCADE,page_id TEXT NOT NULL REFERENCES pages(id) ON DELETE CASCADE,number INTEGER NOT NULL,text TEXT NOT NULL,embedding TEXT,embedding_model TEXT);CREATE TABLE IF NOT EXISTS claims(id TEXT PRIMARY KEY,company_id TEXT NOT NULL,report_id TEXT NOT NULL REFERENCES reports(id) ON DELETE CASCADE,chunk_id TEXT NOT NULL REFERENCES chunks(id) ON DELETE CASCADE,text TEXT NOT NULL,metric TEXT,value DOUBLE PRECISION,unit TEXT,normalized_value DOUBLE PRECISION,normalized_unit TEXT,year INTEGER,baseline_year INTEGER,boundary TEXT,facility_id TEXT REFERENCES facilities(id),claimed_change DOUBLE PRECISION,direction TEXT,sdgs_json TEXT NOT NULL,rationale TEXT NOT NULL,method TEXT NOT NULL,status TEXT NOT NULL,reason_json TEXT NOT NULL DEFAULT '[]',comparison_json TEXT NOT NULL DEFAULT '{}',review_state TEXT NOT NULL DEFAULT 'unreviewed',created_at TEXT NOT NULL);CREATE TABLE IF NOT EXISTS observations(id TEXT PRIMARY KEY,company_id TEXT NOT NULL,facility_id TEXT REFERENCES facilities(id),metric TEXT NOT NULL,value DOUBLE PRECISION NOT NULL,unit TEXT NOT NULL,normalized_value DOUBLE PRECISION NOT NULL,normalized_unit TEXT NOT NULL,year INTEGER NOT NULL,boundary TEXT NOT NULL,source TEXT NOT NULL,report_id TEXT REFERENCES reports(id),created_at TEXT NOT NULL);CREATE TABLE IF NOT EXISTS reviews(id TEXT PRIMARY KEY,company_id TEXT NOT NULL,claim_id TEXT NOT NULL REFERENCES claims(id) ON DELETE CASCADE,user_id TEXT NOT NULL REFERENCES users(id),decision TEXT NOT NULL,rationale TEXT NOT NULL,created_at TEXT NOT NULL);CREATE TABLE IF NOT EXISTS recommendations(id TEXT PRIMARY KEY,company_id TEXT NOT NULL,claim_id TEXT REFERENCES claims(id) ON DELETE CASCADE,title TEXT NOT NULL,action TEXT NOT NULL,priority TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'open',created_at TEXT NOT NULL);CREATE TABLE IF NOT EXISTS jobs(id TEXT PRIMARY KEY,company_id TEXT NOT NULL,report_id TEXT REFERENCES reports(id) ON DELETE CASCADE,type TEXT NOT NULL,status TEXT NOT NULL,progress INTEGER NOT NULL DEFAULT 0,stage TEXT NOT NULL,error TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);CREATE TABLE IF NOT EXISTS environment(id TEXT PRIMARY KEY,company_id TEXT NOT NULL,facility_id TEXT NOT NULL REFERENCES facilities(id),kind TEXT NOT NULL,status TEXT NOT NULL,payload_json TEXT NOT NULL,created_at TEXT NOT NULL);CREATE TABLE IF NOT EXISTS audit(id TEXT PRIMARY KEY,company_id TEXT NOT NULL,user_id TEXT,action TEXT NOT NULL,entity TEXT NOT NULL,entity_id TEXT,metadata_json TEXT NOT NULL,created_at TEXT NOT NULL);CREATE TABLE IF NOT EXISTS evaluation_cases(id TEXT PRIMARY KEY,company_id TEXT NOT NULL,claim_id TEXT NOT NULL REFERENCES claims(id) ON DELETE CASCADE,expected_status TEXT NOT NULL,expected_sdgs TEXT NOT NULL,relevant_chunks TEXT NOT NULL,split TEXT NOT NULL,created_at TEXT NOT NULL);CREATE TABLE IF NOT EXISTS evaluation_runs(id TEXT PRIMARY KEY,company_id TEXT NOT NULL,metrics_json TEXT NOT NULL,created_at TEXT NOT NULL);CREATE INDEX IF NOT EXISTS claim_company ON claims(company_id,report_id);CREATE INDEX IF NOT EXISTS chunk_company ON chunks(company_id,report_id);CREATE INDEX IF NOT EXISTS observation_scope ON observations(company_id,metric,year,boundary);CREATE INDEX IF NOT EXISTS audit_company ON audit(company_id,created_at);
ALTER TABLE recommendations ADD COLUMN IF NOT EXISTS method TEXT NOT NULL DEFAULT 'rules'; ALTER TABLE users ADD COLUMN IF NOT EXISTS disabled INTEGER NOT NULL DEFAULT 0; ALTER TABLE users ADD COLUMN IF NOT EXISTS auth_user_id TEXT UNIQUE;
CREATE TABLE IF NOT EXISTS government_admins(user_id TEXT PRIMARY KEY REFERENCES users(id),authority TEXT NOT NULL,demo_company_id TEXT REFERENCES companies(id));CREATE TABLE IF NOT EXISTS company_registry(company_id TEXT PRIMARY KEY REFERENCES companies(id),licence_number TEXT UNIQUE,licence_status TEXT NOT NULL DEFAULT 'pending',licence_reason TEXT NOT NULL DEFAULT '',public_visible INTEGER NOT NULL DEFAULT 0,publish_environment INTEGER NOT NULL DEFAULT 0,public_description TEXT NOT NULL DEFAULT '',updated_at TEXT NOT NULL);CREATE TABLE IF NOT EXISTS oversight_actions(id TEXT PRIMARY KEY,company_id TEXT NOT NULL REFERENCES companies(id),type TEXT NOT NULL,note TEXT NOT NULL,public_note TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'open',created_by TEXT NOT NULL REFERENCES users(id),created_at TEXT NOT NULL,updated_at TEXT NOT NULL);CREATE TABLE IF NOT EXISTS submissions(id TEXT PRIMARY KEY,company_id TEXT NOT NULL REFERENCES companies(id),text TEXT NOT NULL,year INTEGER NOT NULL,source TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'submitted',review_note TEXT NOT NULL DEFAULT '',submitted_by TEXT NOT NULL REFERENCES users(id),reviewed_by TEXT REFERENCES users(id),created_at TEXT NOT NULL,updated_at TEXT NOT NULL);CREATE TABLE IF NOT EXISTS meter_readings(id TEXT PRIMARY KEY,company_id TEXT NOT NULL REFERENCES companies(id),facility_id TEXT REFERENCES facilities(id),metric TEXT NOT NULL,value DOUBLE PRECISION NOT NULL,unit TEXT NOT NULL,recorded_at TEXT NOT NULL,source TEXT NOT NULL,created_at TEXT NOT NULL);CREATE INDEX IF NOT EXISTS submission_company ON submissions(company_id,created_at);CREATE INDEX IF NOT EXISTS meter_company ON meter_readings(company_id,recorded_at);
CREATE TABLE IF NOT EXISTS metro_cache(city_id TEXT PRIMARY KEY,model_json TEXT,station_json TEXT,last_attempt TEXT,last_success TEXT,next_run TEXT NOT NULL,lease_until TEXT,error TEXT);CREATE TABLE IF NOT EXISTS city_watch(company_id TEXT NOT NULL,city_id TEXT NOT NULL,PRIMARY KEY(company_id,city_id));CREATE TABLE IF NOT EXISTS emission_rules(id TEXT PRIMARY KEY,company_id TEXT NOT NULL,facility_id TEXT NOT NULL,metric TEXT NOT NULL,threshold DOUBLE PRECISION NOT NULL,unit TEXT NOT NULL,window_minutes INTEGER NOT NULL,max_age_minutes INTEGER NOT NULL,measurement_basis TEXT NOT NULL,source_reference TEXT NOT NULL,active INTEGER NOT NULL,created_at TEXT NOT NULL);CREATE TABLE IF NOT EXISTS emission_samples(id TEXT PRIMARY KEY,company_id TEXT NOT NULL,facility_id TEXT NOT NULL,metric TEXT NOT NULL,value DOUBLE PRECISION NOT NULL,unit TEXT NOT NULL,period_start TEXT NOT NULL,period_end TEXT NOT NULL,measurement_basis TEXT NOT NULL,quality TEXT NOT NULL,source_kind TEXT NOT NULL,source_reference TEXT NOT NULL,created_at TEXT NOT NULL);CREATE TABLE IF NOT EXISTS monitoring_alerts(id TEXT PRIMARY KEY,event_key TEXT UNIQUE NOT NULL,scope_key TEXT NOT NULL,company_id TEXT,city_id TEXT,rule_id TEXT,kind TEXT NOT NULL,title TEXT NOT NULL,message TEXT NOT NULL,status TEXT NOT NULL,payload_json TEXT NOT NULL,ai_json TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);CREATE TABLE IF NOT EXISTS monitoring_state(scope_key TEXT PRIMARY KEY,state TEXT NOT NULL,alert_id TEXT);CREATE TABLE IF NOT EXISTS notifications(id TEXT PRIMARY KEY,user_id TEXT NOT NULL,event_key TEXT NOT NULL,alert_id TEXT,title TEXT NOT NULL,message TEXT NOT NULL,kind TEXT NOT NULL,created_at TEXT NOT NULL,read_at TEXT,UNIQUE(user_id,event_key));CREATE TABLE IF NOT EXISTS notification_audit_checkpoint(event_id TEXT PRIMARY KEY);CREATE INDEX IF NOT EXISTS notification_user ON notifications(user_id,created_at);CREATE INDEX IF NOT EXISTS sample_scope ON emission_samples(company_id,facility_id,metric,period_end);